import requests
import json
import pandas as pd
import seaborn as sns
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    try:
        response = requests.get(url, headers=HEADERS, params=parameters)
        response.raise_for_status()
    except requests.exceptions.RequestException as e:
        raise Exception(f"URL cannot be accessed or invalid URL: {e}")

    try:
        data = response.json()
        if not data:
            raise Exception("Empty data received from the API.")
    except json.JSONDecodeError:
        raise Exception("Invalid JSON data received from the API.")

    df = pd.DataFrame(data)

    if df.empty:
        raise Exception("Empty DataFrame created from the API data.")

    numerical_df = df.select_dtypes(include=['number'])

    if numerical_df.empty:
        raise Exception("No numerical data found to calculate correlation.")

    correlation_matrix = numerical_df.corr()

    ax = sns.heatmap(correlation_matrix, annot=True, cmap='coolwarm')
    return df, ax

