import json
import re
from collections import Counter
REPLACE_NONE = "None"
def task_func(json_str):
    data = json.loads(json_str)
    all_values = []
    def process_data(item):
        if isinstance(item, dict):
            keys_to_remove = []
            for k, v in item.items():
                if v is None:
                    keys_to_remove.append(k)
                elif isinstance(v, str) and re.match(r"[^@]+@[^@]+\.[^@]+", v):
                    item[k] = REPLACE_NONE
                    all_values.append(REPLACE_NONE)
                elif isinstance(v, (dict, list)):
                    process_data(v)
                    all_values.append(v)
                else:
                    all_values.append(v)
            for k in keys_to_remove:
                del item[k]
        elif isinstance(item, list):
            i = 0
            while i < len(item):
                if item[i] is None:
                    item.pop(i)
                elif isinstance(item[i], str) and re.match(r"[^@]+@[^@]+\.[^@]+", item[i]):
                    item[i] = REPLACE_NONE
                    all_values.append(REPLACE_NONE)
                    i += 1
                elif isinstance(item[i], (dict, list)):
                    process_data(item[i])
                    all_values.append(item[i])
                    i += 1
                else:
                    all_values.append(item[i])
                    i += 1
    process_data(data)
    value_counts = Counter(str(v) if not isinstance(v, (dict, list)) else json.dumps(v, sort_keys=True) for v in all_values)
    return {"data": data, "value_counts": value_counts}

